// Mesma lista/ids do array OBRAS em prototipo/index.html -- igual ao fluxo
// de Pedidos (Suprimentos), essa API exige `obra_id` por chamada (sem
// endpoint "lista todas as obras"), então a lista fixa é inevitável.
// CNPEM - Auditório (id 103) fica DE FORA de propósito, mesma decisão já
// tomada nos outros 2 fluxos de ingestão. Se uma obra nova entrar no
// painel, adicionar aqui também.
const OBRAS = [
  { id: 106, nome: 'CNPEM - Faseado' },
  { id: 110, nome: 'Hitachi' },
  { id: 94,  nome: 'Porto Itapoá' },
  { id: 107, nome: 'Novo Nordisk - AP' },
  { id: 108, nome: 'Novo Nordisk - AP - Reforço' },
  { id: 91,  nome: 'Novo Nordisk - UB/SP' },
];

return OBRAS.map(o => ({ json: { id_obra: o.id, nome_obra: o.nome } }));

// Modo padrão "Run Once for All Items" (não mexer) -- mesmo motivo do
// fluxo de Pedidos (Suprimentos): a saída é um FAN-OUT de 1 item de obra
// pra N linhas de item de mapa de compras.
//
// Casa cada resposta HTTP com sua obra de origem por POSIÇÃO (mesma ordem
// de entrada/saída). Guard explícito: se as contagens não baterem, aborta
// em vez de arriscar juntar item com obra errada.
const listaObras = $('Lista de obras').all();
const respostas = $input.all();
if (listaObras.length !== respostas.length) {
  throw new Error(`Descompasso entre lista de obras (${listaObras.length}) e respostas HTTP (${respostas.length}) -- abortando pra não misturar item com obra errada.`);
}

// Conversão numérica defensiva -- a API irmã (pedidos_usuarios_api) já
// devolveu valor monetário como STRING ("418607.66") apesar da doc dizer
// "número" (ver README do fluxo de Orçamentos Complementares). Sem essa
// conversão, um valor assim viraria texto dentro de uma coluna numeric e o
// insert falharia (ou, pior, uma coluna numeric aceitaria a string mas o
// front-end que já usa Number()/parseValNum() ficaria duplicando o cast).
const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);

return respostas.map((resp, i) => {
  const idObra = listaObras[i].json.id_obra;
  const nomeObra = listaObras[i].json.nome_obra;
  const corpo = resp.json;

  // FORMATO DO ENVELOPE AINDA NÃO CONFIRMADO com dado real -- o guia da API
  // não mostra um exemplo de JSON completo pra /v1/itens (só a tabela de
  // campos). A API irmã da mesma família (pedidos_usuarios_api) devolve
  // `{ data: [...] }`, então essa é a 1ª tentativa; cai pra array direto
  // como 2ª tentativa. Se nenhuma bater, o erro abaixo aparece na 1ª
  // execução real em vez de gravar silenciosamente 0 linhas -- ajustar
  // aqui assim que a forma real for vista (ex.: pode ser `{ items: [...] }`
  // ou vir com metadados de paginação por fora do array).
  const itens = Array.isArray(corpo?.data) ? corpo.data
    : Array.isArray(corpo) ? corpo
    : (() => { throw new Error(`Formato de resposta inesperado pra obra ${idObra} (nem {data:[...]} nem array direto) -- confira a resposta real e ajuste este node antes de reexecutar.`); })();

  const linhas = itens.map(it => ({
    id_obra: idObra,
    obra_nome: nomeObra,
    id_mapa_compras: num(it.id_mapa_compras),
    requisicao: it.requisicao != null ? String(it.requisicao) : null,
    codigo_seq: it.codigo_seq != null ? String(it.codigo_seq) : null,
    descricao: it.descricao || null,
    unidade: it.unidade || null,
    quantidade: num(it.quantidade),
    preco_referencia_bd_s1: num(it.preco_referencia_bd_s1),
    subtotal_referencia_bd_s1: num(it.subtotal_referencia_bd_s1),
    custo_meta_orcamento: num(it.custo_meta_orcamento),
    subtotal_custo_meta_orcamento: num(it.subtotal_custo_meta_orcamento),
    saldo_orcamentario: num(it.saldo_orcamentario),
    saldo_quantidade: num(it.saldo_quantidade),
    quantidade_pedida: num(it.quantidade_pedida),
    total_consumido: num(it.total_consumido),
    tem_pedido: it.tem_pedido === true || it.tem_pedido === 'true' || it.tem_pedido === 1,
    fornecedor_ref: it.fornecedor_ref || null,
    projeto_ref: it.projeto_ref || null,
    // Nomes exatos de melhor_oferta_* NÃO confirmados pela doc (ela só diz
    // "unitário/subtotal/fornecedor", sem nomear os campos JSON de verdade)
    // -- ajustar assim que a resposta real chegar. `raw` guarda o item
    // inteiro, então nada se perde mesmo se estes 3 vierem null por nome
    // errado.
    melhor_oferta_unitario: num(it.melhor_oferta_unitario),
    melhor_oferta_subtotal: num(it.melhor_oferta_subtotal),
    melhor_oferta_fornecedor: it.melhor_oferta_fornecedor || null,
    raw: it,
    atualizado_em: new Date().toISOString(),
  }));
  return { json: { id_obra: idObra, linhas } };
});
